import {workStore} from './work-store.mjs?v=15';
import {escapeHTML as e} from './engine.mjs?v=17';
import {databaseExamEngine} from './db-exam.mjs?v=23';
export function databaseExamPage({view,crumb,sidebar,course='database'}){
 const {units,writtenQuestions,quizCount,totalQuestions,createExam,cleanExam,examQuestions,remainingSeconds,submitExam,examResult}=databaseExamEngine(course),title=course==='intermediate'?'DATA6222 Intermediate':'DATA6211 Introduction';
 let s=workStore.read('db-exam:'+course,null,cleanExam),timer=null,disposed=false;
 const $=q=>view.querySelector(q),save=()=>workStore.write('db-exam:'+course,s);
 const stop=()=>{if(timer!==null)clearInterval(timer);timer=null;};
 const focusHeading=()=>{const h=$('h1');h.tabIndex=-1;h.focus({preventScroll:true});h.scrollIntoView({block:'start',behavior:'instant'});};
 const done=()=>{stop();submitExam(s);save();results();focusHeading();};
 const expired=()=>{if(s&&s.submittedAt===null&&remainingSeconds(s)===0){done();return true;}return false;};
 const intro=()=>crumb('Database practice exams')+`<p class="eyebrow">DATABASE REVISION</p><h1>${title} practice exam</h1>`;
 function setup(){stop();view.innerHTML=intro()+`<p class="lede">Practise across all ${units.length} units, then review your reasoning.</p><div class="exam-overview"><section class="panel"><h2>What to expect</h2><ul><li>${quizCount} automatically marked questions, two per unit: ${quizCount} marks.</li><li>Two written SQL or design tasks: 20 self-assessed marks.</li><li>Worked answers unlock after you submit the whole attempt.</li><li>Each attempt draws a different mix from the existing lesson quiz bank. The two written tasks stay the same.</li></ul><p>No account is needed. This is revision practice, not a secure or institution-issued examination.</p></section><section class="panel"><h2>Choose your pace</h2><form id="exam-start"><label class="field-label" for="exam-duration">Time limit</label><select id="exam-duration"><option value="0">Untimed</option><option value="30">30 minutes</option><option value="60">60 minutes</option></select><p>For timed attempts, the clock keeps running if you leave, refresh or close this page. At the deadline, saved answers are submitted when this exam is open or next reopened.</p><p>Work saves in this browser when storage is available. People sharing this browser profile share this attempt.</p>${s?'<p class="note">Starting replaces your previous practice exam in this browser.</p>':''}<div class="button-row"><button class="button" type="submit">Start practice exam</button>${s?'<button class="button secondary" type="button" id="exam-return">Return to saved attempt</button>':''}</div></form></section></div>`;
 $('#exam-start').onsubmit=event=>{event.preventDefault();const seed=crypto.getRandomValues(new Uint32Array(1))[0]||1;s=createExam(seed,Number($('#exam-duration').value));save();attempt();focusHeading();};if($('#exam-return'))$('#exam-return').onclick=()=>{if(s.submittedAt!==null)results();else attempt();};sidebar();}
 function attempt(){stop();if(expired())return;const qs=examQuestions(s.seed),answered=qs.filter(q=>Number.isInteger(s.answers[q.id])).length+writtenQuestions.filter(q=>(s.written[q.id]||'').trim()).length;
 view.innerHTML=intro()+`<div class="exam-status panel"><div><strong>${answered} of ${totalQuestions} answered</strong><p>${quizCount} quiz marks + 20 self-assessed written marks</p></div><div><span>Time remaining</span><strong id="exam-clock"></strong></div><button class="button" id="exam-submit">Submit exam</button></div><nav class="exam-nav" aria-label="Exam questions">${Array.from({length:totalQuestions},(_,i)=>{const q=i<quizCount?qs[i]:writtenQuestions[i-quizCount],filled=i<quizCount?Number.isInteger(s.answers[q.id]):!!(s.written[q.id]||'').trim();return `<button class="button ${s.index===i?'':'secondary'}" data-exam-q="${i}" aria-label="Question ${i+1}${filled?', answered':', unanswered'}" ${s.index===i?'aria-current="step"':''}>${i+1}${filled?' ✓':''}</button>`;}).join('')}</nav><section class="panel exam-question" id="exam-question" tabindex="-1"></section><div class="button-row"><button class="button secondary" id="exam-prev" ${s.index===0?'disabled':''}>Previous question</button><button class="button secondary" id="exam-next" ${s.index===totalQuestions-1?'disabled':''}>Next question</button><button class="button ghost" id="exam-clear">Clear this answer</button></div><p class="note">You can leave questions unanswered and return before submission. No answers or hints are shown during the attempt. Your written work is self-assessed after submission.</p><dialog id="exam-confirm" aria-labelledby="exam-confirm-title"><h2 id="exam-confirm-title">Submit this attempt?</h2><p id="exam-submit-summary"></p><p>You cannot edit exam answers after submitting. Worked solutions and the written marking checklist will unlock.</p><div class="button-row"><button class="button secondary" id="exam-keep">Keep working</button><button class="button" id="exam-finish">Submit and see answers</button></div></dialog>`;
 const i=s.index,q=i<quizCount?qs[i]:writtenQuestions[i-quizCount];$('#exam-question').innerHTML=`<p class="eyebrow">QUESTION ${i+1} / UNIT ${q.unit>100?q.unit-100:q.unit} / ${i<quizCount?'1 MARK':'10 SELF-ASSESSED MARKS'}</p>${i<quizCount?`<fieldset><legend>${e(q.question)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="exam-choice" value="${j}" ${s.answers[q.id]===j?'checked':''}><span>${e(o)}</span></label>`).join('')}</fieldset>`:`<h2>${e(q.title)}</h2><p>${e(q.prompt)}</p><label class="field-label" for="exam-written">Your SQL or design answer</label><textarea class="editor" id="exam-written" spellcheck="false" maxlength="10000" placeholder="Write the requested SQL or table design and explain your checks...">${e(s.written[q.id]||'')}</textarea>`}`;
 const updateAnswered=()=>{const n=qs.filter(q=>Number.isInteger(s.answers[q.id])).length+writtenQuestions.filter(q=>(s.written[q.id]||'').trim()).length;$('.exam-status strong').textContent=`${n} of ${totalQuestions} answered`;const filled=i<quizCount?Number.isInteger(s.answers[q.id]):!!s.written[q.id]?.trim(),b=$(`[data-exam-q="${i}"]`);b.textContent=String(i+1)+(filled?' ✓':'');b.setAttribute('aria-label',`Question ${i+1}, ${filled?'answered':'unanswered'}`);};
 view.querySelectorAll('[name="exam-choice"]').forEach(input=>input.onchange=()=>{if(expired())return;s.answers[q.id]=Number(input.value);save();updateAnswered();});if($('#exam-written'))$('#exam-written').oninput=event=>{if(expired())return;s.written[q.id]=event.target.value;save();updateAnswered();};
 const move=i=>{if(expired())return;s.index=i;save();attempt();$('#exam-question').focus({preventScroll:true});$('#exam-question').scrollIntoView({block:'start',behavior:'instant'});};view.querySelectorAll('[data-exam-q]').forEach(b=>b.onclick=()=>move(Number(b.dataset.examQ)));$('#exam-prev').onclick=()=>move(s.index-1);$('#exam-next').onclick=()=>move(s.index+1);$('#exam-clear').onclick=()=>{if(expired())return;if(i<quizCount)delete s.answers[q.id];else s.written[q.id]='';save();attempt();};
 $('#exam-submit').onclick=()=>{if(expired())return;const n=qs.filter(q=>!Number.isInteger(s.answers[q.id])).length+writtenQuestions.filter(q=>!(s.written[q.id]||'').trim()).length;$('#exam-submit-summary').textContent=n?`${n} questions are unanswered. Unanswered quiz questions receive 0 marks.`:`All ${totalQuestions} questions have an answer.`;$('#exam-confirm').showModal();};$('#exam-keep').onclick=()=>$('#exam-confirm').close();$('#exam-finish').onclick=done;
 const tick=()=>{if(disposed||expired())return;const n=remainingSeconds(s);$('#exam-clock').textContent=n===null?'Untimed':`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};tick();if(s.submittedAt===null&&s.deadline)timer=setInterval(tick,1000);sidebar();}
 function results(){stop();const qs=examQuestions(s.seed),r=examResult(s);view.innerHTML=intro()+`<p class="lede">${s.expired?'Time ended. Your saved answers have been submitted.':'Attempt submitted. Review your answers and plan your revision.'}</p><div class="exam-scores"><section class="panel"><h2>Automatically marked</h2><strong>${r.objective} / ${quizCount}</strong><p>Quiz questions only</p></section><section class="panel"><h2>Written self-assessment</h2><strong id="exam-self-score"></strong><p id="exam-combined"></p></section></div><section class="panel"><h2>Where to revise</h2><p>These suggestions use this attempt’s two quiz questions per unit, not a complete measure of mastery.</p><ul>${r.byUnit.map(u=>`<li><a class="text-link" href="#db-unit/${u.id}">Unit ${u.id>100?u.id-100:u.id}: ${e(u.title)}</a> - ${u.correct}/2. ${u.correct<2?'Review missed concepts and try the related lessons.':'Both correct in this attempt.'}</li>`).join('')}</ul></section><h2>Quiz review</h2>${qs.map((q,i)=>{const a=s.answers[q.id];return `<details class="panel exam-review"><summary>Question ${i+1} / Unit ${q.unit>100?q.unit-100:q.unit} - ${a===q.correct?'Correct':'0 marks'}</summary><p><strong>${e(q.question)}</strong></p><p>Your answer: ${Number.isInteger(a)?e(q.options[a]):'Unanswered'}</p><p>Correct answer: ${e(q.options[q.correct])}</p><p>${e(q.explanation)}</p></details>`;}).join('')}<h2>Written solutions and marking checklist</h2><p>Self-assessment is your own judgement. For each criterion, choose 0 (not met), 1 (partly met) or 2 (fully met). Other correct solutions can earn the same marks. Compare against the requirement and test cases.</p>${writtenQuestions.map((q,i)=>`<section class="panel exam-review"><h3>Question ${quizCount+1+i}: ${e(q.title)}</h3><p>${e(q.prompt)}</p><h4>Your submitted work</h4><pre class="code-block"><code>${e(s.written[q.id]?.trim()||'No answer submitted.')}</code></pre><h4>Worked solution</h4><pre class="code-block"><code>${e(q.solution)}</code></pre><p>${e(q.explanation)}</p><fieldset><legend>Your marking checklist / 10 marks</legend>${q.criteria.map((c,j)=>`<label class="exam-criterion"><span>${e(c)}</span><select data-rubric="${q.id}" data-criterion="${j}" aria-label="Question ${quizCount+1+i}, criterion ${j+1}"><option value="">Choose marks</option>${[0,1,2].map(v=>`<option value="${v}" ${s.ratings[q.id]?.[j]===v?'selected':''}>${v} - ${['Not met','Partly met','Fully met'][v]}</option>`).join('')}</select></label>`).join('')}</fieldset></section>`).join('')}<div class="button-row"><button class="button" id="exam-new">Set up another attempt</button><button class="button secondary" id="exam-print">Print results / save PDF</button><a class="button secondary" href="#db-practice">More database practice</a></div><p class="note">This practice result is not an official grade. Answers are stored in this browser, and solutions are inspectable in client-side source. There are no student accounts or lecturer submissions.</p>`;
 function scores(){const x=examResult(s);$('#exam-self-score').textContent=`${x.self} / 20 (${x.rated}/10 criteria rated)`;$('#exam-combined').textContent=x.combined===null?'Complete all 10 criteria to calculate a combined practice total.':`Combined practice total: ${x.combined} / ${quizCount+20}. Includes your self-assessed marks.`;}scores();view.querySelectorAll('[data-rubric]').forEach(input=>input.onchange=()=>{s.ratings[input.dataset.rubric]??=Array(5).fill(null);s.ratings[input.dataset.rubric][Number(input.dataset.criterion)]=input.value===''?null:Number(input.value);save();scores();});$('#exam-new').onclick=setup;$('#exam-print').onclick=()=>{view.querySelectorAll('.exam-review').forEach(d=>{if(d.tagName==='DETAILS')d.open=true;});window.print();};sidebar();}
 if(s){if(s.submittedAt!==null)results();else attempt();}else setup();return()=>{disposed=true;stop();};
}
